import{_ as e,o as t,c as r,ag as a}from"./chunks/framework.Cyu1VozZ.js";const p=JSON.parse('{"title":"Using the Board","description":"","frontmatter":{},"headers":[],"relativePath":"board/using-the-board.md","filePath":"board/using-the-board.md"}'),n={name:"board/using-the-board.md"};function s(i,o,l,d,h,g){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="using-the-board" tabindex="-1">Using the Board <a class="header-anchor" href="#using-the-board" aria-label="Permalink to &quot;Using the Board&quot;">​</a></h1><p>A <strong>board</strong> is an infinite, freeform canvas — a Miro/FigJam-style whiteboard for sketching ideas, arranging sticky notes, and collaborating in real time. Unlike a slide, a board has no fixed page size: you pan and zoom across a boundless plane.</p><h2 id="create-a-board" tabindex="-1">Create a board <a class="header-anchor" href="#create-a-board" aria-label="Permalink to &quot;Create a board&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>New Board</strong></li></ol><p>The board opens with an empty canvas and appears in your workspace document list.</p><h2 id="move-around-the-canvas" tabindex="-1">Move around the canvas <a class="header-anchor" href="#move-around-the-canvas" aria-label="Permalink to &quot;Move around the canvas&quot;">​</a></h2><ul><li><strong>Scroll or two-finger swipe</strong> pans across the plane</li><li><strong>⌘/Ctrl + wheel</strong> (or a trackpad pinch) zooms about the pointer, so the point under the cursor stays where it is</li><li><strong>Hold Space and drag</strong>, or <strong>drag with the middle mouse button</strong>, to pan without disturbing whatever is under the pointer. An ordinary drag still selects, moves, or resizes.</li><li><strong>Zoom ▾</strong> in the toolbar offers fixed steps (50%, 75%, 100%, 150%, 200%) and <strong>Fit</strong>, which frames everything on the board. The range runs from 10% to 800% — wider than a slide&#39;s, because an infinite plane gets surveyed further out and inspected further in.</li><li>The <strong>minimap</strong> in the bottom-right corner shows the whole board at a glance; drag inside it to jump to another area, and use its <strong>Map ▾</strong> button to collapse it out of the way</li></ul><p>An existing board <strong>opens framed on its content</strong> rather than at the empty world origin, so you never have to hunt for it — which matters most for an imported board, whose content can sit a long way from that origin.</p><p>Right-clicking empty canvas gives you <strong>Paste</strong>, <strong>Select all</strong>, <strong>Fit to content</strong>, and <strong>Snap to grid</strong>.</p><h2 id="the-toolbar" tabindex="-1">The toolbar <a class="header-anchor" href="#the-toolbar" aria-label="Permalink to &quot;The toolbar&quot;">​</a></h2><p>The toolbar morphs with what you are doing. With nothing selected it runs, left to right:</p><ul><li><strong>Undo / Redo</strong></li><li><strong>Zoom ▾</strong></li><li><strong>Grid ▾</strong> — the background grid: <strong>None</strong>, <strong>Dot grid</strong> (the default), or <strong>Line grid</strong>, plus a separate <strong>Snap to grid</strong> checkbox that quantizes moves and resizes onto the grid. The two are independent, so snapping still works with the grid hidden. Both are your own view settings, remembered in this browser rather than stored in the board, so every collaborator picks their own.</li><li><strong>Select</strong> (<code>Esc</code>) — select, move, and resize existing items</li><li><strong>Text box</strong> — drop freeform text anywhere on the canvas</li><li><strong>Sticky note ▾</strong> — clicking drops a yellow sticky; the chevron next to it opens a 6-color palette. Text inside a sticky shrinks to fit.</li><li><strong>Insert image</strong> — opens a file picker (PNG, JPEG, GIF, or WebP). You can also paste or drag an image straight onto the canvas.</li><li><strong>Shape ▾</strong> — a picker of 137 shapes across eight categories: Shapes, Block Arrows, Banners, Flowchart, Callouts, Equation, Stars, and Action Buttons</li><li><strong>Line ▾</strong> — <strong>Line</strong>, <strong>Arrow</strong>, <strong>Elbow connector</strong>, <strong>Curved connector</strong>, and a freehand <strong>Scribble</strong>. Connectors snap onto a shape&#39;s connection points as you draw, and an attached endpoint follows its shape when the shape moves.</li></ul><h3 id="when-something-is-selected" tabindex="-1">When something is selected <a class="header-anchor" href="#when-something-is-selected" aria-label="Permalink to &quot;When something is selected&quot;">​</a></h3><p>Extra controls appear at the end of the toolbar, depending on what you picked:</p><ul><li><strong>Shapes and connectors</strong> — <strong>Fill</strong> (a solid color or a gradient; connectors have no fill) and <strong>Border</strong> (color, weight, dash)</li><li><strong>Images</strong> — <strong>Crop</strong> and <strong>Reset crop</strong>. <em>Replace</em> is not wired up on a board; insert a new image instead.</li><li><strong>Text boxes</strong> — the box&#39;s own background fill and border</li><li><strong>Arrange</strong> — <strong>Group</strong> / <strong>Ungroup</strong>, <strong>Order</strong> (bring to front or forward, send backward or to back), <strong>Align</strong> (needs two or more selected), <strong>Distribute</strong> (three or more), and <strong>Rotate 90°</strong> either way</li></ul><p>Double-click an item to edit its text, and the toolbar switches again: font family and size, bold, italic, underline, text color, clear formatting, paragraph alignment, bulleted and numbered lists, and indentation — then <strong>Done</strong> (or <code>Esc</code>) to come back out.</p><h2 id="collaborate" tabindex="-1">Collaborate <a class="header-anchor" href="#collaborate" aria-label="Permalink to &quot;Collaborate&quot;">​</a></h2><p>Boards sync in real time through the same collaboration engine as the rest of Wafflebase. Changes appear instantly for everyone, and you see each teammate&#39;s live <strong>cursor</strong> as well as their <strong>selection</strong> — whatever they have picked up is ringed in their color, so you can tell what someone is about to move before they move it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Share a board the same way as any other document — see <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a>. Viewers with read-only access can still pan and zoom around the board.</p></div><h2 id="import-a-miro-board" tabindex="-1">Import a Miro board <a class="header-anchor" href="#import-a-miro-board" aria-label="Permalink to &quot;Import a Miro board&quot;">​</a></h2><p>An existing Miro board can come in as a new Wafflebase board. The entry is <strong>Import from Miro…</strong>, in the workspace <strong>New</strong> dropdown — not on the board itself, since the import creates the document. You paste a Miro access token and the board URL; the token is used for that one import and is never stored. See <a href="/docs/guide/import-export.html">Import &amp; Export</a> for what comes across and what doesn&#39;t.</p><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h2><p>Boards are versioned like every other editable document type. Click the <strong>history</strong> icon in the header to browse earlier versions, open one read-only, and roll the board back. See <a href="/docs/guide/version-history.html">Version History</a>.</p>',23)])])}const b=e(n,[["render",s]]);export{p as __pageData,b as default};
